// Lightweight article index for tool pages and other client bundles.
// Imports ONLY src/content/blog/articles-index.json (metadata, a few KB) —
// never articles.json — so article bodies stay out of every page bundle.
// The index is generated by scripts/build-articles-content.mjs (runs in `prebuild`).
import rawIndex from "@/content/blog/articles-index.json";

export interface ArticleLite {
  slug: string;
  title: string;
  description: string;
  category: string;
  publishedAt: string;
  /** toolId of the article's primary tool CTA (null if none). */
  toolId: string | null;
}

const index = rawIndex as ArticleLite[];

// Must mirror TOOL_CATEGORY_MAP in blog-utils.getArticlesForTool.
const TOOL_CATEGORY_MAP: Record<string, string[]> = {
  compress: ["compression", "security"],
  sanitize: ["security", "legal"],
  edit: ["security", "archiving", "legal"],
  sign: ["legal", "security"],
  merge: ["archiving", "compression"],
  split: ["compression", "archiving"],
  rotate: ["archiving"],
  scan: ["archiving", "security"],
  convert: ["archiving", "compression"],
  imagesToPdf: ["archiving", "compression"],
  pdfToImages: ["archiving", "compression"],
  watermark: ["security", "legal"],
  compressImage: ["compression", "guides"],
};

function getAllArticlesLite(): ArticleLite[] {
  return [...index].sort(
    (a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime()
  );
}

/**
 * Same selection algorithm as blog-utils.getArticlesForTool:
 * exact toolId matches first, then preferred categories, then most recent.
 */
export function getArticlesForTool(toolId?: string, count = 3): ArticleLite[] {
  const all = getAllArticlesLite();
  if (!toolId) return all.slice(0, count);

  const exactMatches = all.filter((a) => a.toolId === toolId);
  if (exactMatches.length >= count) {
    return exactMatches.slice(0, count);
  }

  const preferredCategories = TOOL_CATEGORY_MAP[toolId] || ["security", "compression"];
  const catMatches = all.filter(
    (a) =>
      preferredCategories.includes(a.category) &&
      !exactMatches.some((m) => m.slug === a.slug)
  );

  const combined = [...exactMatches, ...catMatches];
  if (combined.length >= count) {
    return combined.slice(0, count);
  }

  const fallback = all.filter((a) => !combined.some((c) => c.slug === a.slug));
  return [...combined, ...fallback].slice(0, count);
}
